CREATE DATABASE IF NOT EXISTS comandas_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE comandas_db;
-- La base ya existe en MySQL. Este archivo sirve como respaldo del modelo.
-- No incluye DROP TABLE para no borrar los datos del equipo.
CREATE TABLE Usuario (Id_usuario INT UNSIGNED NOT NULL AUTO_INCREMENT, Nombre VARCHAR(80) NOT NULL, Apellido VARCHAR(80) NOT NULL, Clave VARCHAR(255) NOT NULL, Rol ENUM('mesero','cajero','cocina','admin') NOT NULL, PRIMARY KEY (Id_usuario));
CREATE TABLE Cliente (Id_cliente INT UNSIGNED NOT NULL AUTO_INCREMENT, Nombre VARCHAR(80) NOT NULL, Correo VARCHAR(120) NOT NULL UNIQUE, Contrasena VARCHAR(255) NOT NULL, Telefono VARCHAR(20) NOT NULL, Fecha_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (Id_cliente));
CREATE TABLE Producto (Id_producto INT UNSIGNED NOT NULL AUTO_INCREMENT, Nombre VARCHAR(120) NOT NULL, Categoria VARCHAR(60) NOT NULL, Precio DECIMAL(10,2) NOT NULL, Disponible TINYINT(1) NOT NULL DEFAULT 1, PRIMARY KEY (Id_producto));
CREATE TABLE Inventario (Id_inventario INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_producto INT UNSIGNED NOT NULL UNIQUE, Stock INT UNSIGNED NOT NULL DEFAULT 0, Fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (Id_inventario), CONSTRAINT fk_inv_producto FOREIGN KEY (Id_producto) REFERENCES Producto(Id_producto) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE Comanda (Id_comanda INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_usuario INT UNSIGNED NULL, Id_cliente INT UNSIGNED NULL, Num_mesa TINYINT UNSIGNED NOT NULL, Fecha DATE NOT NULL, Hora TIME NOT NULL, Origen ENUM('mesero','app') NOT NULL, Estado_comanda ENUM('por_confirmar','en_cocina','lista','entregada','por_cobrar','pagada') NOT NULL DEFAULT 'por_confirmar', PRIMARY KEY (Id_comanda), CONSTRAINT fk_com_usuario FOREIGN KEY (Id_usuario) REFERENCES Usuario(Id_usuario) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT fk_com_cliente FOREIGN KEY (Id_cliente) REFERENCES Cliente(Id_cliente) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE Pedido (Id_pedido INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_comanda INT UNSIGNED NOT NULL, Excepciones VARCHAR(255) NULL, Estado_pedido ENUM('en_cocina','listo') NOT NULL DEFAULT 'en_cocina', PRIMARY KEY (Id_pedido), CONSTRAINT fk_ped_comanda FOREIGN KEY (Id_comanda) REFERENCES Comanda(Id_comanda) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE Item_pedido (Id_item INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_pedido INT UNSIGNED NOT NULL, Id_producto INT UNSIGNED NOT NULL, Cantidad TINYINT UNSIGNED NOT NULL DEFAULT 1, Precio_unitario DECIMAL(10,2) NOT NULL, Subtotal DECIMAL(10,2) NOT NULL, PRIMARY KEY (Id_item), CONSTRAINT fk_item_pedido FOREIGN KEY (Id_pedido) REFERENCES Pedido(Id_pedido) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT fk_item_producto FOREIGN KEY (Id_producto) REFERENCES Producto(Id_producto) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE Recibo (Id_recibo INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_comanda INT UNSIGNED NOT NULL UNIQUE, Id_usuario INT UNSIGNED NULL, Monto_total DECIMAL(10,2) NOT NULL, Fecha_emision DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, Detalles TEXT NULL, PRIMARY KEY (Id_recibo), CONSTRAINT fk_rec_comanda FOREIGN KEY (Id_comanda) REFERENCES Comanda(Id_comanda) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT fk_rec_usuario FOREIGN KEY (Id_usuario) REFERENCES Usuario(Id_usuario) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE Pago (Id_pago INT UNSIGNED NOT NULL AUTO_INCREMENT, Id_recibo INT UNSIGNED NOT NULL UNIQUE, Metodo_pago ENUM('efectivo','tarjeta','app') NOT NULL, Origen ENUM('caja','app') NOT NULL, Fecha_pago DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, Monto_total DECIMAL(10,2) NOT NULL, Cantidad_cuentas TINYINT UNSIGNED NOT NULL DEFAULT 1, PRIMARY KEY (Id_pago), CONSTRAINT fk_pago_recibo FOREIGN KEY (Id_recibo) REFERENCES Recibo(Id_recibo) ON DELETE RESTRICT ON UPDATE CASCADE);
